const pack=f=>new Promise((ok,no)=>{const fr=new FileReader();fr.onerror=()=>no(new Error('No se pudo leer el archivo.'));
 if(f.type.startsWith('image/')){fr.onload=()=>{const i=new Image();i.onload=()=>{const k=Math.min(1,1280/Math.max(i.width,i.height)),c=document.createElement('canvas');c.width=i.width*k;c.height=i.height*k;c.getContext('2d').drawImage(i,0,0,c.width,c.height);const d=c.toDataURL('image/jpeg',.78);d.length>900000?no(new Error('La imagen es demasiado grande.')):ok({name:f.name,type:'image/jpeg',data:d})};i.onerror=()=>no(new Error('Imagen no válida.'));i.src=fr.result};fr.readAsDataURL(f)}
 else{if(f.size>650000)return no(new Error('El archivo supera 650 KB.'));fr.onload=()=>ok({name:f.name,type:f.type,data:fr.result});fr.readAsDataURL(f)}});
