const reqTabs=()=>`<div class=row style="margin-bottom:12px">${[['','Todas'],['PENDIENTE','Pendientes'],['ACEPTADA','Aceptadas'],['RECHAZADA','Rechazadas']].map(([k,l])=>`<button class="btn ${(S.rf||'')===k?'p':''}" data-a=rf data-v="${k}">${l} (${k?mine().filter(r=>r.status===k).length:mine().length})</button>`).join('')}</div>`;
const rcell=(r,who)=>{const ss=r.sesion||'Confirmada';let h='';if(who==='m'&&r.status==='PENDIENTE')h+=`<button class="btn g" data-a=acc data-id=${r.id}>Aceptar</button> <button class="btn d" data-a=rej data-id=${r.id}>Rechazar</button>`;
 if(r.status==='ACEPTADA'){if(/^https:\/\//.test(r.meetLink||''))h+=`<a class="btn g" target=_blank rel=noopener href="${esc(r.meetLink)}">🎥 Unirme a Meet</a> `;if(who==='m'){h+=`<button class=btn data-a=meet data-id=${r.id}>🎥 ${r.meetLink?'Cambiar':'Añadir'} enlace Meet</button> `;if(ss==='Confirmada')h+=`<button class="btn ${r.live?'d':''}" data-a=live data-id=${r.id}>${r.live?'⏹ Terminar clase en vivo':'🔴 Iniciar clase en vivo'}</button> `;h+=`<button class=btn data-a=grade data-id=${r.student}>⭐ Calificar alumno</button>`}
  if(who==='s'&&ss==='Confirmada')h+=`<button class="btn d" data-a=ses data-s=Cancelada data-id=${r.id}>Cancelar</button>`;
  if(who==='s'&&ss==='Finalizada'&&!S.rats.some(x=>x.id===r.id))h+=`<select data-in=rate data-id=${r.id}><option value="">Calificar</option>${[5,4,3,2,1].map(v=>`<option>${v}</option>`).join('')}</select>`}return h};
let subs=[];
/* ---------- AUTH ---------- */
onAuthStateChanged(auth,async u=>{subs.forEach(f=>f());subs=[];S.ready=false;Object.assign(S,{users:[],reqs:[],msgs:[],notifs:[],rats:[],grades:[],chats:[],chat:null,view:'',q:'',fd:'',fe:0});
 if(!u){S.me=null;return render()}
 await T(async()=>{let d=await getDoc(doc(db,'users',u.uid));
  if(!d.exists()){const isA=(cfg.adminEmails||[]).includes(u.email);if(isA&&!u.emailVerified){await sendEmailVerification(u);toast('Te enviamos un correo de verificación. Verifícalo y vuelve a iniciar sesión.',1);S.pending=null;return signOut(auth)}if(!S.pending&&isA)S.pending={name:'',role:'student'};if(!S.pending){toast('Tu cuenta fue eliminada o no está registrada.',1);return signOut(auth)}
   await setDoc(doc(db,'users',u.uid),{...S.pending,role:(cfg.adminEmails||[]).includes(u.email)&&u.emailVerified?'admin':S.pending.role,name:S.pending.name||u.displayName||u.email,email:u.email,photo:u.photoURL||'',active:true,created:Date.now(),skills:[],availability:[],studentsCount:0});S.pending=null;d=await getDoc(doc(db,'users',u.uid))}
  if(d.data().active===false){toast('Tu cuenta está desactivada. Contacta al administrador.',1);return signOut(auth)}
  S.me={id:u.uid,...d.data()};if(!S.me.name){S.me.name=u.displayName||u.email;await updateDoc(doc(db,'users',u.uid),{name:S.me.name})}S.view='';listen();render()});if(!S.me)render()});
function listen(){const ad=S.me.role==='admin',id=S.me.id,M=c=>ad?collection(db,c):query(collection(db,c),where('members','array-contains',id)),
 on=(q,k,first)=>subs.push(onSnapshot(q,s=>{S[k]=s.docs.map(d=>({id:d.id,...d.data()}));if(first){S.ready=true;const m=S.users.find(x=>x.id===id);if(m){if(m.active===false)return signOut(auth);S.me=m}}refresh()},e=>{if(first){S.ready=true;refresh()}toast('Error de base de datos ('+(e.code||e.message)+'). Revisa que Firestore esté creado y las reglas publicadas.',1)}));
 on(collection(db,'users'),'users',1);on(M('requests'),'reqs');if(!ad)on(M('messages'),'msgs');if(ad)on(collection(db,'chats'),'chats');on(ad?collection(db,'notifications'):query(collection(db,'notifications'),where('to','==',id)),'notifs');on(collection(db,'ratings'),'rats');on(collection(db,'grades'),'grades')}
