 if(!S.ready)return A.innerHTML='<p style="padding:40px">Cargando datos…</p>';
 const m=MENU[S.me.role];if(!m.some(x=>x[0]===S.view))S.view=m[0][0];const un=S.notifs.filter(n=>!n.read&&n.to===S.me.id).length;
